const grid=document.querySelector('#artworks');let filtered=artworks;
function render(filter='All'){filtered=artworks.filter(a=>filter==='All'||a.tags.includes(filter));grid.replaceChildren();for(const art of filtered){const card=document.createElement('article');card.className='art-card';const btn=document.createElement('button');btn.dataset.art=art.id;btn.setAttribute('aria-label',`View ${art.title}`);const img=document.createElement('img');img.src=`assets/${art.src}`;img.alt=art.alt;img.loading='lazy';if(art.frame)img.className='framed-art';if(art.category==='Christmas Collection'){const crop=document.createElement('span');crop.className='frame-window';crop.append(img);btn.append(crop);btn.classList.add('christmas-display')}else{btn.append(img)};const title=document.createElement('h3');title.textContent=art.title;const category=document.createElement('p');category.textContent=art.id==='oval'?'RELATED PRESENTATION':art.category;card.append(btn,title,category);grid.append(card)}document.querySelector('#gallery-status').textContent=`${filtered.length} images shown`;}
render();
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#navigation');
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});nav.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
const dialog=document.querySelector('#viewer'),image=document.querySelector('#viewer-image'),scroll=document.querySelector('#image-scroll'),crop=document.querySelector('#viewer-crop');let collection=[],index=0,mode='fit',scale=1,lastFocus=null;
function layout(){if(!dialog.open||!image.naturalWidth)return;const width=scroll.clientWidth-32,height=scroll.clientHeight-32;const trimmed=collection[index]?.src.startsWith('christmas-');const naturalWidth=trimmed?1388:image.naturalWidth,naturalHeight=trimmed?1336:image.naturalHeight;const base=mode==='width'?width/naturalWidth:Math.min(width/naturalWidth,height/naturalHeight,1);const w=Math.max(1,naturalWidth*base*scale);crop.classList.toggle('frame-window',trimmed);crop.style.width=w+'px';crop.style.height=(naturalHeight*base*scale)+'px';image.style.width=trimmed?'110.662824%':'100%';image.style.height='auto';document.querySelector('#zoom-label').textContent=scale===1?(mode==='width'?'Width':'Fit'):Math.round(scale*100)+'%';}
image.addEventListener('load',layout);new ResizeObserver(layout).observe(scroll);
function show(){const item=collection[index];mode='fit';scale=1;document.querySelector('#viewer-title').textContent=item.title;document.querySelector('#viewer-kind').textContent=item.category;document.querySelector('#viewer-caption').textContent=item.provenance;image.alt=item.alt;image.src=`assets/${item.src}`;scroll.scrollTop=0;scroll.scrollLeft=0;document.querySelector('#previous').disabled=collection.length<2;document.querySelector('#next').disabled=collection.length<2;requestAnimationFrame(layout);}
function open(items,i){collection=items;index=i;lastFocus=document.activeElement;dialog.showModal();document.body.style.overflow='hidden';show();document.querySelector('.close').focus();}
function step(n){index=(index+n+collection.length)%collection.length;show()}
document.addEventListener('click',e=>{const filter=e.target.closest('[data-filter]');if(filter){document.querySelectorAll('[data-filter]').forEach(b=>{const on=b===filter;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on))});render(filter.dataset.filter);return;}const art=e.target.closest('[data-art]');if(art){const list=art.closest('#artworks')?filtered:artworks;open(list,list.findIndex(a=>a.id===art.dataset.art));return;}const doc=e.target.closest('[data-doc]');if(doc){open(documents,Number(doc.dataset.doc));return;}const scene=e.target.closest('[data-scene]');if(scene)open(scenes,Number(scene.dataset.scene));});
document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.body.style.overflow='';lastFocus?.focus()});dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();step(1)}if(e.key==='ArrowLeft'){e.preventDefault();step(-1)}});
document.querySelector('#previous').addEventListener('click',()=>step(-1));document.querySelector('#next').addEventListener('click',()=>step(1));document.querySelector('#zoom-in').addEventListener('click',()=>{scale=Math.min(6,scale+.5);layout()});document.querySelector('#zoom-out').addEventListener('click',()=>{scale=Math.max(.5,scale-.5);layout()});document.querySelector('#fit').addEventListener('click',()=>{mode='fit';scale=1;layout()});document.querySelector('#fit-width').addEventListener('click',()=>{mode='width';scale=1;layout()});
